package com.fintaxpro;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import com.fasterxml.jackson.databind.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;
@RestController public class AiController{
 final String key,model,mlUrl,mlKey;final ObjectMapper json;final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).build();
 AiController(@Value("${fintax.gemini-key}")String k,@Value("${fintax.gemini-model}")String m,@Value("${fintax.ml-url}")String u,@Value("${fintax.ml-key}")String mk,ObjectMapper j){key=k;model=m;mlUrl=u;mlKey=mk;json=j;}
 @GetMapping("/api/status") Map<String,Object> status(){return Map.of("gemini",!key.isBlank()&&!model.isBlank(),"ml",!mlUrl.isBlank()&&!mlKey.isBlank(),"taxYear","AY 2026–27","forecast","Deterministic scheduled cash flow");}
 @PostMapping("/api/classify") Map<String,Object> classify(@RequestBody Map<String,String>d)throws Exception{String desc=d.getOrDefault("description","");String direction=d.getOrDefault("direction","");if(desc.isBlank()||desc.length()>255||!List.of("INCOME","EXPENSE").contains(direction))throw new IllegalArgumentException("Invalid transaction description or direction.");if(!mlUrl.isBlank()&&!mlKey.isBlank()){try{var req=HttpRequest.newBuilder(URI.create(mlUrl.replaceAll("/$","")+"/classify")).header("Content-Type","application/json").header("X-API-Key",mlKey).timeout(Duration.ofSeconds(6)).POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(d))).build();var r=client.send(req,HttpResponse.BodyHandlers.ofString());if(r.statusCode()==200){Map<String,Object> result=json.readValue(r.body(),new com.fasterxml.jackson.core.type.TypeReference<>(){});if(List.of("BUSINESS","PERSONAL").contains(result.get("scope")))return result;}}catch(Exception ignored){}}String v=desc.toLowerCase(Locale.ROOT);String scope=v.matches(".*(client|freelanc|office|business|invoice|hosting|software|figma|adobe|project|domain).*")?"BUSINESS":"PERSONAL";String category=v.contains("rent")?"Rent":v.matches(".*(electric|internet|phone|bill).*")?"Utilities":v.matches(".*(software|figma|adobe|hosting|subscription).*")?"Software":v.matches(".*(grocery|food|coffee|restaurant).*")?"Food & groceries":v.matches(".*(uber|fuel|transport|travel).*")?"Travel":v.matches(".*(client|project|freelanc|invoice).*")?"Client payment":v.contains("salary")?"Salary":direction.equals("INCOME")?"Other income":"Other expense";return Map.of("scope",scope,"category",category,"source","RULES");}
 @PostMapping("/api/advisor") ResponseEntity<?> advisor(@RequestBody Map<String,String>d){if(key.isBlank()||model.isBlank())return ResponseEntity.status(503).body(Map.of("error","Configure GEMINI_API_KEY and GEMINI_MODEL on the server."));String q=d.getOrDefault("question","");if(q.isBlank()||q.length()>2000)throw new IllegalArgumentException("Ask a question under 2,000 characters.");try{Map<String,Object> body=Map.of("systemInstruction",Map.of("parts",List.of(Map.of("text","You are FinTaxPro, an educational finance assistant for India. Only answer bookkeeping, finance and tax education questions. No ledger or verified tax references are supplied. Do not claim access to accounts or live regulations. Do not compute final tax. Refer current-rule questions to incometax.gov.in and a qualified CA. Never request credentials, PAN, OTPs or passwords. Keep answers concise."))),"contents",List.of(Map.of("role","user","parts",List.of(Map.of("text",q)))),"generationConfig",Map.of("maxOutputTokens",900));HttpRequest req=HttpRequest.newBuilder(URI.create("https://generativelanguage.googleapis.com/v1beta/models/"+URLEncoder.encode(model,java.nio.charset.StandardCharsets.UTF_8)+":generateContent")).timeout(Duration.ofSeconds(25)).header("Content-Type","application/json").header("x-goog-api-key",key).POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build();var response=client.send(req,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)throw new IllegalStateException();JsonNode parts=json.readTree(response.body()).path("candidates").path(0).path("content").path("parts");StringBuilder answer=new StringBuilder();for(JsonNode part:parts)answer.append(part.path("text").asText());if(answer.isEmpty())throw new IllegalStateException();return ResponseEntity.ok(Map.of("answer",answer.toString(),"source","Gemini · general guidance; not independently verified"));}catch(Exception e){return ResponseEntity.status(502).body(Map.of("error","Advisor unavailable. Please retry."));}}
}
